class Solution {
    public int maxOperations(String s) {
        int ans = 0;
        int ones = 0;
        int n = s.length();
        int i = 0;
        while (i < n) {
            if (s.charAt(i) == '1') {
                ones++;
                i++;
            } else {
                ans += ones;
                while (i < n && s.charAt(i) == '0') {
                    i++;
                }
            }
        }
        return ans;
    }
}

var maxOperations = function(s) {
    let ans = 0;
    let ones = 0;
    const n = s.length;
    let i = 0;
    while (i < n) {
        if (s[i] === '1') {
            ones++;
            i++;
        } else {
            ans += ones;
            while (i < n && s[i] === '0') {
                i++;
            }
        }
    }
